const b = $json.body || {};
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof b.campaign_id !== 'string' || !uuidRe.test(b.campaign_id)) {
  throw new Error('campaign_id missing or not a valid UUID: ' + JSON.stringify(b.campaign_id));
}
if (!b.proposed_action || typeof b.proposed_action !== 'object' || !b.proposed_action.action_type) {
  throw new Error('proposed_action missing or malformed: ' + JSON.stringify(b.proposed_action));
}
const chatId = (typeof b.chat_message_id === 'string' && uuidRe.test(b.chat_message_id)) ? b.chat_message_id : null;
return [{ json: { campaign_id: b.campaign_id, chat_message_id: chatId, proposed_action: b.proposed_action } }];

const campaign = $('Get campaign').item.json;
if (!campaign || !campaign.id) throw new Error('Campaign not found.');
const token = $('Get Meta credentials').item.json.system_user_token;
if (!token) throw new Error('meta_ads_settings.system_user_token is not set.');
const API = 'https://graph.facebook.com/v21.0';
const action = $('Validate input').item.json.proposed_action;

const campaignId = campaign.meta_campaign_id;
const adsetId = campaign.meta_adset_id;
const adId = campaign.meta_ad_id;

const ops = []; // { url, form: {field: value} }
let campaignStatusValue = campaign.status;
let newBudgetUsd = campaign.daily_budget_usd;

if (action.action_type === 'update_daily_budget') {
  if (typeof action.daily_budget_usd !== 'number') throw new Error('proposed_action.daily_budget_usd is missing or not a number.');
  if (!adsetId) throw new Error('This campaign has no meta_adset_id on file — cannot set the budget (Meta budgets live on the ad set).');
  // Meta wants the budget in the account currency MINOR unit (cents for USD).
  ops.push({ url: API + '/' + adsetId, form: { daily_budget: String(Math.round(action.daily_budget_usd * 100)) } });
  newBudgetUsd = action.daily_budget_usd;
} else if (action.action_type === 'pause_campaign') {
  if (!campaignId) throw new Error('This campaign has no meta_campaign_id on file.');
  ops.push({ url: API + '/' + campaignId, form: { status: 'PAUSED' } });
  campaignStatusValue = 'paused';
} else if (action.action_type === 'resume_campaign') {
  if (!campaignId) throw new Error('This campaign has no meta_campaign_id on file.');
  // Activating a Meta parent does NOT cascade to children — set each level we know.
  ops.push({ url: API + '/' + campaignId, form: { status: 'ACTIVE' } });
  if (adsetId) ops.push({ url: API + '/' + adsetId, form: { status: 'ACTIVE' } });
  if (adId) ops.push({ url: API + '/' + adId, form: { status: 'ACTIVE' } });
  campaignStatusValue = 'active';
} else {
  throw new Error('Unknown proposed_action.action_type: ' + action.action_type);
}

return ops.map(op => ({ json: {
  url: op.url,
  form: op.form,
  access_token: token,
  campaignRowId: campaign.id,
  actionType: action.action_type,
  campaignStatusValue,
  newBudgetUsd,
} }));
